/* 互动小说增强系统 —— 酒馆助手引导器
 * 作用：把扩展本体注入到真正的酒馆页面（父页面），而不是脚本 iframe 内，
 * 这样模式切换按钮、输入框接管与世界书写入都作用于真实界面。
 * 扩展本体由 jsdelivr 提供，推送后自动跟随更新（缓存约 12 小时）。
 */
(() => {
    const SRC = 'https://testingcf.jsdelivr.net/gh/KarasjokMing/tauritavern-if-enhancer@main/index.js';
    const doc = (window.parent && window.parent.document) || document;
    if (doc.getElementById('tt-if-enhancer-loader')) {
        console.log('[IF Enhancer] 引导器已注入，跳过重复加载。');
        return;
    }
    const script = doc.createElement('script');
    script.id = 'tt-if-enhancer-loader';
    script.type = 'module';
    script.src = SRC;
    script.onerror = () => console.error('[IF Enhancer] 扩展本体加载失败，请检查网络或改用扩展安装方式。');
    doc.body.appendChild(script);
    console.log('[IF Enhancer] 已请求加载扩展本体：' + SRC);
})();
